parameters.query:
UPDATE hotline.call_events SET status = 'EXTRACTED', updated_at = now()
 WHERE conversation_id = $1 AND status IN ('RECEIVED', 'FORWARDED')
RETURNING conversation_id;

parameters.jsCode:
// One place that joins config + call + validated extraction and pre-formats
// the text used by Slack and Salesforce. Everything downstream reads
// $('Lead Context').first().json.
const cfg = $('Config').first().json;
const ext = $('Extract').first().json;
const o = ext.output || {};
const c = o.contact || {};
const b = o.budget || {};

const s = (v) => (typeof v === 'string' && v.trim() !== '' ? v.trim() : null);
const human = (v) => (v ? String(v).replace(/_/g, ' ') : 'unknown');
// Slack mrkdwn escaping, so caller-provided text cannot inject mentions or links.
const esc = (v) => String(v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const score = Number(o.buying_intent_score);
const ratingBand = score >= 7 ? 'Hot' : score >= 4 ? 'Warm' : 'Cold';

let budgetText;
if (!b.mentioned) {
  budgetText = 'not mentioned';
} else if (b.amount_usd === null || b.amount_usd === undefined) {
  budgetText = 'mentioned, amount not stated' + (b.period && b.period !== 'unknown' ? ` (${human(b.period)})` : '');
} else {
  budgetText = '$' + Number(b.amount_usd).toLocaleString('en-US', { maximumFractionDigits: 2 }) +
    (b.period && b.period !== 'unknown' ? ' ' + human(b.period) : '');
}

const name = [s(c.first_name), s(c.last_name)].filter(Boolean).join(' ') || 'Unknown caller';
const company = s(c.company) || 'Unknown company';
const title = s(c.job_title);
const timeoutH = Number(cfg.APPROVAL_TIMEOUT_H);

const sfDescription = [
  `Need: ${o.need_summary || 'not stated'}`,
  `Budget: ${budgetText}`,
  `Timeline: ${human(o.timeline)}`,
  `Decision maker: ${human(o.decision_maker)}`,
  `Intent evidence: ${o.intent_evidence || 'none'}`,
  `Intent score: ${score}/10 (${ext.prompt_version}, ${ext.model})`,
  `Conversation ID: ${cfg.conversation_id}`,
].join('\n');

const approvalMessage = [
  '*Hot lead awaiting approval*',
  `*Name:* ${esc(name)}${title ? ` (${esc(title)})` : ''}`,
  `*Company:* ${esc(company)}`,
  `*Intent score:* ${score}/10`,
  `*Evidence:* ${esc(o.intent_evidence || 'none')}`,
  `*Budget:* ${esc(budgetText)}`,
  `*Timeline:* ${esc(human(o.timeline))}`,
  `*Decision maker:* ${esc(human(o.decision_maker))}`,
  `*Summary:* ${esc(o.call_summary || '')}`,
  `_Approve writes a Hot Lead to Salesforce. Reject writes nothing. Expires in ${timeoutH} h. Conversation ${esc(cfg.conversation_id)}._`,
].join('\n');

const headerText = `:telephone_receiver: New hot lead needs approval: *${esc(name)}* (${esc(company)}), ` +
  `intent ${score}/10. Details and decision in this thread.`;

return [{
  json: {
    conversation_id: cfg.conversation_id,
    caller_phone: s(cfg.caller_phone),
    received_at: cfg.received_at,
    threshold: Number(cfg.INTENT_APPROVAL_THRESHOLD),
    approval_timeout_min: Math.max(1, Math.round(timeoutH * 60)),
    sf_base: cfg.SALESFORCE_INSTANCE_URL,
    sf_api_version: cfg.SF_API_VERSION,
    approval_channel: cfg.SLACK_APPROVAL_CHANNEL,
    prompt_version: ext.prompt_version,
    model: ext.model,
    extraction_attempt: ext.attempt,
    output: o,
    is_sales_lead: o.is_sales_lead === true,
    score,
    rating_band: ratingBand,
    display_name: name,
    company,
    budget_text: budgetText,
    sf_description: sfDescription,
    approval_message: approvalMessage,
    approval_header: headerText,
  },
}];

parameters.query:
UPDATE hotline.decisions SET approval_outcome = 'APPROVED', approver = $2, decided_at = now()
 WHERE conversation_id = $1
RETURNING conversation_id;

parameters.jsCode:
// Shared Salesforce write chain entry (auto-write and approved paths).
// Maps the extraction to Lead fields per PRD §6.6. The input item carries the
// path parameters: route, expected_status, rating, approval_outcome, approver.
const ctx = $('Lead Context').first().json;
const p = $input.first().json;
const o = ctx.output || {};
const c = o.contact || {};

const s = (v) => (typeof v === 'string' && v.trim() !== '' ? v.trim() : null);
const cut = (v, n) => (v ? v.slice(0, n) : v); // Salesforce standard field lengths

if (!ctx.sf_base) throw new Error('SALESFORCE_INSTANCE_URL is not set in the n8n environment');

const email = s(c.email);
const emailOk = !!email && /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);

const lead = {
  // Conversation_Id__c is the upsert key; it is in the URL, not the body.
  FirstName: cut(s(c.first_name), 40),
  LastName: cut(s(c.last_name), 80) || 'Unknown caller',
  Company: cut(s(c.company), 255) || 'Unknown (voice inbound)',
  Email: emailOk ? cut(email, 80) : null,
  Phone: cut(s(c.phone) || s(ctx.caller_phone), 40),
  Title: cut(s(c.job_title), 128),
  LeadSource: 'Phone Inquiry',
  Rating: p.rating || ctx.rating_band,
  Intent_Score__c: ctx.score,
  Description: ctx.sf_description + (email && !emailOk ? `\nEmail as heard (not a valid address): ${email}` : ''),
};
// Blank fallback = omit the field (an update then keeps what is already there).
for (const k of Object.keys(lead)) {
  if (lead[k] === null || lead[k] === undefined || lead[k] === '') delete lead[k];
}

const api = `${ctx.sf_base}/services/data/${ctx.sf_api_version}`;

return [{
  json: {
    conversation_id: ctx.conversation_id,
    route: p.route,
    expected_status: p.expected_status,
    rating: lead.Rating,
    intent_score: ctx.score,
    approval_outcome: p.approval_outcome || null,
    approver: p.approver || null,
    lead_upsert_url: `${api}/sobjects/Lead/Conversation_Id__c/${encodeURIComponent(ctx.conversation_id)}`,
    lead_body: lead,
    task_url: `${api}/sobjects/Task`,
    task_subject: 'Voice qualification call',
    task_activity_date: $now.toFormat('yyyy-MM-dd'),
    task_description: String(o.call_summary || ''),
  },
}];

// Error output of "SF Upsert Lead" / "SF Create Task" (after the node's own
// retries), pre-extracted by "SF Error Detail". Classifies the failure and extracts the Salesforce error body so
// the alert and call_events.last_error ("<node>: <message>") are useful.
const d = $input.first().json || {};
const failedNode = d.failed_node || 'Salesforce';
const w = $('Build SF Lead').first().json;
let e;
try { e = JSON.parse(d.error_json || 'null'); } catch (err) { e = d.error_json; }

// n8n's error item: {message, description, httpCode?, cause: {name, message: '400 - "<SF body>"'}}
function statusOf(err) {
  if (!err || typeof err !== 'object') return null;
  const cause = err.cause || {};
  const cand = err.httpCode || err.statusCode || err.status || (err.response && err.response.status) ||
    cause.status || cause.statusCode || (cause.response && cause.response.status);
  if (cand && /^\d{3}$/.test(String(cand))) return Number(cand);
  for (const t of [cause.message, err.message]) {
    const m = String(t || '').match(/^\s*([1-5]\d\d)\b/);
    if (m) return Number(m[1]);
  }
  return null;
}

function bodyOf(err) {
  if (err === null || err === undefined) return 'unknown error';
  if (typeof err !== 'object') return String(err);
  const cause = err.cause || {};
  let body = (cause.message && String(cause.message).replace(/^\s*\d{3}\s*-\s*/, '')) ||
    err.description || err.error || (err.response && (err.response.data || err.response.body)) || '';
  if (body && typeof body !== 'string') body = JSON.stringify(body);
  // Salesforce returns a JSON string inside the message; unwrap one level of quoting.
  try { const un = JSON.parse(body); if (typeof un === 'string') body = un; } catch (e) { /* keep as is */ }
  const msg = err.message ? String(err.message) : '';
  return [msg, body && body !== msg ? body : ''].filter(Boolean).join(' | ') || JSON.stringify(err);
}

const MAX_ATTEMPTS = 3; // 1 try + 2 retries for 5xx / timeout (PRD §6.7)
const attempt = Number(d.attempt) || 1;
const status = statusOf(e);
const clientError = !!status && status >= 400 && status < 500;
const retry = !clientError && attempt < MAX_ATTEMPTS;
let kind;
if (clientError) kind = 'Salesforce rejected the request (4xx, not retried)';
else if (status && status >= 500) kind = `Salesforce server error (5xx) after ${attempt} attempt(s)`;
else kind = `timeout or network error after ${attempt} attempt(s)`;

const message = `${status || 'no status'} ${kind}: ${bodyOf(e)}`.slice(0, 2000);

return [{
  json: {
    conversation_id: w.conversation_id,
    expected_status: w.expected_status,
    route: w.route,
    failed_node: failedNode,
    attempt,
    retry,
    http_status: status,
    error_message: message,
    last_error: `${failedNode}: ${message}`.slice(0, 1000),
  },
}];
